nce                            .font(.subheadline)                            .bold()                            .multilineTextAlignment(.center)                            .padding(.horizontal)                    }                                                            // Conditionally show the Resend Button                    if showResendButton {                        Button(action: resendVerificationEmail) {                            Text("Resend Verification Email")                                .font(.subheadline)                                .foregroundColor(.white)                                .underline()                        }                        .padding(.top, 5)                    }                                        // Action Button                    Button(action: loginUser) {                        Text("Login")                            .font(.headline)                            .foregroundColor(.orange)                            .frame(maxWidth: .infinity)                            .padding()                            .background(Color.white)                            .cornerRadius(12)                    }                    .padding(.horizontal, 30)                    .padding(.top, 10)                                        // Navigation Link to Signup                    NavigationLink(destination: SignupView()) {                        Text("New Here? Sign up")                            .foregroundColor(.white)                            .underline()                            .padding(.top, 20)                    }                }            }        }    }        func loginUser() {            errorMessage = ""            successMessage = ""            showResendButton = false                        Auth.auth().signIn(withEmail: email, password: password) { result, error in                if let error = error {                    errorMessage = error.localizedDescription                    return                }                                guard let user = result?.user else { return }                                // THE BOUNCER CHECK                if user.isEmailVerified {                    print("Successfully logged in and verified!")                    // TODO: Send them to the GrubU Home Feed                } else {                    // They aren't verified, but we KEEP them signed in temporarily                    errorMessage = "Please verify your .edu email address before logging in."                    showResendButton = true // Reveal the button!                }            }        }                func resendVerificationEmail() {            // We clear previous messages so the user sees the UI update            errorMessage = ""            successMessage = "Sending..."                        // Grab the currently logged-in user and send the email            Auth.auth().currentUser?.sendEmailVerification { error in                if let error = error {                    successMessage = ""                    errorMessage = "Failed to resend: \(error.localizedDescription)"                } else {                    successMessage = "A fresh link has been sent to \(email)!"                    showResendButton = false // Hide the button once sent to prevent spamming                                        // Now that the email is sent, we safely kick them out of the vault                    try? Auth.auth().signOut()                }            }        }}                struct LoginView_Previews: PreviewProvider {        static var previews: some View {            LoginView()        }    }